// Normalize Greenhouse API shapes to the matcher record shape.
// Malformed items go to the quarantine list, never crash the run.
const quarantine = [];
function stripHtml(s){ return (s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(); }
const out = [];
for (const input of $input.all()) {
  const jobs = input.json.jobs || [];
  const company = input.params?.company || 'unknown';
  for (const j of jobs) {
    try {
      if (!j.title) { quarantine.push({reason:'missing title', id: j.id}); continue; }
      out.push({ json: {
        source: 'greenhouse-live', company,
        source_id: String(j.id), title: j.title,
        url: j.absolute_url, location_text: (j.location||{}).name || '',
        department: ((j.metadata||[]).find(m=>m.name==='Department')||{}).value || '',
        text: stripHtml(j.content)
      }});
    } catch (e) { quarantine.push({reason: 'normalize: '+e.message, id: j.id}); }
  }
}
return out;

// Opportunity Matcher scoring — mirrors matcher.py exactly.
// Weights and thresholds are JUDGMENT; document any change here.
const W = { role: .30, audience: .20, materials: .20, gap: .15, company: .15 };
const T = { PURSUE: .65, NETWORK: .45, WATCH: .25 };
const ROLE = {'developer education':1,'developer educator':1,'advocate':1,'evangelist':1,'learning experience':1,'education lead':1,'educator':.9,'curriculum':.8,'instructional':.8,'content engineer':.8,'documentation':.7,'education':.7,'workshop':.6,'technical writer':.6,'enablement':.6,'training':.4,'professor':.5,'teacher':.5,'learning':.3,'content':.3};
const AUD = {university:.5,universities:.5,college:.5,campus:.5,student:.5,students:.5,school:.4,schools:.4,developer:.3,developers:.3,partner:.15,partners:.15,community:.15,customer:.1,customers:.1,public:.1};
const MAT = ['develop curriculum','create curriculum','build curriculum','own the curriculum','own the documentation','create tutorials','write documentation','develop training','build training','create course','develop course','instructional design','learning experience','enablement program','certification program'];
const GAP = ['design system','design token','certification','give talks','public speaking','keynote','evangelist','developer relations','run workshops','lead workshops','host workshops','facilitat'];
const CO = {anthropic:1,stripe:.6,canva:.6,openai:.6,notion:.6,figma:.4,webflow:.4,writer:.4,miro:.4,jasper:.4,replit:.6,meta:.5};
function score(r){
  const title=(r.title||'').toLowerCase(), text=(r.text||'').toLowerCase();
  const signals=[];
  const audH=Object.keys(AUD).filter(a=>new RegExp('\\b'+a+'\\b').test(text));
  const matH=MAT.filter(p=>text.includes(p));
  let roleFit=0;
  const hits=Object.entries(ROLE).filter(([w])=>title.includes(w)).sort((a,b)=>b[1]-a[1]);
  if(hits.length){ const [w,wt]=hits[0];
    if(wt<.7 && !audH.length && !matH.length){ signals.push(`role: '${w}' discounted and unconfirmed — not counted`); }
    else { roleFit=wt; signals.push(`role: title matches '${w}' (${wt})`); } }
  const audFit=Math.min(1,audH.reduce((s,a)=>s+AUD[a],0));
  if(audH.length) signals.push('audience: '+audH.slice(0,4).join(', '));
  const mat=(matH.length?.5:0)+(matH.length&&audH.length?.5:0);
  if(matH.length) signals.push(`materials: '${matH[0]}'`+(audH.length?' + named audience':''));
  const gapH=GAP.filter(g=>text.includes(g));
  const gapF=Math.min(1,.34*gapH.length);
  if(gapH.length) signals.push('gap: '+gapH.slice(0,3).join(', '));
  const co=CO[(r.company||'').toLowerCase()] ?? .5;
  signals.push(`${r.company} demand ${co}`);
  const fit=+(W.role*roleFit+W.audience*audFit+W.materials*mat+W.gap*gapF+W.company*co).toFixed(3);
  const decision=fit>=T.PURSUE?'PURSUE':fit>=T.NETWORK?'NETWORK':fit>=T.WATCH?'WATCH':'SKIP';
  return {...r, fit, decision, signals};
}
return $input.all().map(i=>({json: score(i.json)}));

// One human-readable markdown brief per actionable role.
// This is the OUTPUT a non-technical person opens — not JSON.
return $input.all().map(i=>{ const r=i.json;
  const md = `# ${r.title}

${r.company} — ${r.location_text}

Fit ${r.fit} → **${r.decision}**

## Why

` +
    r.signals.map(s=>`- ${s}`).join('
') +
    `

## Posting

${r.url}

## Suggested next step

` +
    (r.decision==='PURSUE' ? 'Draft the application; it names the target directly.
'
                           : 'Find the human; the terms or the team need a conversation first.
');
  return {json: {...r, brief_markdown: md}}; });

